[
  {
    "title": "kick-foot-not-visible",
    "claim": "In Image #4, the raised leg under FRONT KICK ends at a trouser cuff with no visible foot, whereas Image #22 shows a bare foot during the same named technique.",
    "reason": "The foot helps players read the strike’s reach, but these stills cannot establish whether the difference comes from animation phase, artwork, or texture clipping.",
    "suggest": "Capture the pose ID, animation phase, and atlas UVs matching Image #4; inspect that exact source cell and repair any confirmed foot clipping rather than changing the whole kick animation."
  },
  {
    "title": "unmapped-stick-directions",
    "claim": "In Image #15, both sticks show directional chevrons and STANCE or TECHNIQUE labels, but no visible direction-to-action mapping.",
    "reason": "The control names alone do not tell a player which direction produces a punch, kick, jump, or crouch.",
    "suggest": "Keep readable action labels beside the corresponding stick directions, using the mapping already displayed in Image #3 and adjusting layout rather than shrinking text."
  },
  {
    "title": "opening-card-omits-goal",
    "claim": "The opening card in Image #2 explains combining technique and stance inputs but does not state the first-to-two-points objective described in Image #6.",
    "reason": "Players see how to issue a move before seeing what wins the round.",
    "suggest": "Add a short rule beneath the input instruction: “One clean contact ends the exchange. First to 2 points wins.”"
  },
  {
    "title": "score-call-needs-translation",
    "claim": "Image #20 pairs a half-point scoreboard value with WAZA-ARI, but the callout does not explicitly say HALF POINT.",
    "reason": "The scoreboard and callout agree, but players unfamiliar with the terminology must decode that relationship themselves.",
    "suggest": "Add HALF POINT beneath WAZA-ARI and FULL POINT beneath IPPON while retaining the existing technique name."
  },
  {
    "title": "winner-heading-wrap-varies",
    "claim": "ASMONGOLD WINS occupies two lines in Image #18, while HASANABI WINS occupies one line in Image #8.",
    "reason": "The same result hierarchy changes with the winner’s name, making the score’s placement less consistent.",
    "suggest": "Give both result headings the same two-line structure: fighter name first, WINS second, without reducing the font size."
  }
]
